const items = $input.all();
const nuevosItems = [];

// SPEC 32: anuncio determinista del carrito (independiente del LLM).
// Se anexa cuando el negocio tiene el carrito activo (el system prompt trae
// el bloque), la salida no lo contiene y no hay activación de flujo ni menú.
const systemPrompt = (() => {
  try {
    return $('Obtener_configuracion_agente').item.json.system_prompt || '';
  } catch (e) {
    return '';
  }
})();
const carritoActivo = systemPrompt.indexOf('=== CARRITO DE COMPRA ===') !== -1;
const ANUNCIO = '\n💡 Escribe «carrito» para ver nuestro catálogo y comprar por WhatsApp.';

for (const item of items) {
  const output = item.json.output || '';
  const esActivacionFlujo = !!(item.json.flow_name || item.json.equipo_asignado);
  const esMenu = item.json.isMenu === true || item.json.tipoPregunta === 'MENU';
  const anunciar = carritoActivo && output
    && output.indexOf('«carrito»') === -1
    && !esActivacionFlujo && !esMenu;

  const text = anunciar ? output + ANUNCIO : output;
  const nuevoItem = {
    json: {
      ...item.json,
      output: text,
      text: text,
      content: text
    }
  };
  nuevosItems.push(nuevoItem);
}

return nuevosItems;

// Separar_variables_en_json - versión con recuperación extra para strings como: {}, "equipo_asignado":...
const items = $input.all();
const nuevosItems = [];

function detectarSiNo(texto) {
  if (!texto || typeof texto !== 'string') return false;
  const patrones = [
    /\b(sí|si)\s*\/\s*no\b/i,
    /\b(aceptas|confirmas|estás de acuerdo|quieres|deseas|te gustaría)\b.*\?/i,
    /^.*\?.*(sí|si).*(no).*$/i,
    /¿(deseas|quieres|te gustaría|estás seguro|aceptas)/i,
    /\b(yes|no)\b/i,
    /\b(responder (sí|si|no))\\b/i
  ];
  return patrones.some(p => p.test(texto));
}

const mapeoFlowBase = {
  'Agendamiento_Directo': 'flujo_agendamiento_directo',
  'Agendamiento_Precios': 'flujo_agendamiento_precios',
  'Agendamiento_Servicios': 'flujo_agendamiento_servicios',
  'Agendamiento_Otra_Consulta': 'flujo_agendamiento_otra_consulta',
  'Ventas': 'flujo_ventas',
  'CITAS_MP': 'flujo_citas_medios_propios',
  'CITAS_SEGUROS': 'flujo_citas_seguro',
  'RESULTADOS_LAB': 'flujo_resultados_laboratorio',
  'RESULTADOS_IMAGENES': 'flujo_resultados_imagenes'
};

// Merge dinámico: Odoo amplía el mapeo base con flow_map (defaults preservados).
let flowMapOdoo = {};
try {
  flowMapOdoo = $('Obtener_configuracion_agente').item.json.flow_map || {};
} catch (e) {
  flowMapOdoo = {};
}
const mapeoFlow = Object.assign({}, mapeoFlowBase, flowMapOdoo);
const flowPorDefecto = 'flujo_agendamiento_default';

// Red de seguridad: texto a usar cuando el agente no produjo output (p. ej.
// intención FALLBACK sin respuesta). Prioriza el fallback_message de Odoo.
// SPEC 18: menu_enabled (Odoo) decide modo menú (SPEC 13/17) vs conversacional.
let menuEnabled = false;
try {
  menuEnabled = $('Obtener_configuracion_agente').item.json.menu_enabled === true;
} catch (e) {
  menuEnabled = false;
}
let fallbackTexto = menuEnabled
  ? 'Disculpa, no entendí 🤔 ¿Puedes reformularlo? Escribe *menu* para ver las opciones.'
  : 'Disculpa, no entendí 🤔 ¿Me lo cuentas con otras palabras? Con gusto te respondo con la información del negocio.';
try {
  const fb = $('Obtener_configuracion_agente').item.json.fallback_message;
  if (fb && typeof fb === 'string' && fb.trim()) fallbackTexto = fb.trim();
} catch (e) {
  // sin Obtener_configuracion_agente se usa el texto por defecto
}

// --- Sistema del menú determinista (SPEC 13) ---
// El menú se sirve desde el system_prompt (única fuente, SPEC 03), sin IA ni RAG.
const systemPrompt = (() => {
  try {
    return $('Obtener_configuracion_agente').item.json.system_prompt || '';
  } catch (e) {
    return '';
  }
})();

const MENU_MARKER = '=== MENÚ DE OPCIONES ===';
const menuTexto = (() => {
  const idx = systemPrompt.indexOf(MENU_MARKER);
  if (idx === -1) return null;
  const resto = systemPrompt.slice(idx + MENU_MARKER.length);
  const fin = resto.search(/\n=== /);
  const seccion = (fin === -1 ? resto : resto.slice(0, fin)).trim();
  return seccion || null;
})();

const keywordsMenu = (() => {
  for (const linea of systemPrompt.split('\n')) {
    if (linea.includes('(muestra el menú)')) {
      const m = linea.match(/palabras clave:\s*([^\n→]+)/);
      if (m) {
        return m[1].split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
      }
    }
  }
  return [];
})();

function tryParseJSON(rawStr) {
  // Limpiar delimitadores markdown ```json ... ``` o ``` ... ```
  let cleaned = rawStr.trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

  // Intento directo con string limpio
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // preparación secundaria: limpieza
    let attempt = cleaned;
    // eliminar prefijo "{}," si existe
    attempt = attempt.replace(/^\s*\{\}\s*,\s*/, '');
    // eliminar comas solitarias al inicio
    attempt = attempt.replace(/^\s*,\s*/, '');
    // eliminar comas antes de cierre de objeto o array
    attempt = attempt.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
    // si no empieza con { pero hay un } al final, añadimos '{' delante
    if (!attempt.startsWith('{') && attempt.indexOf('}') !== -1) {
      attempt = '{' + attempt;
    }
    // si no termina con } y hay una { en el string, cerramos con }
    if (!attempt.endsWith('}') && attempt.indexOf('{') !== -1) {
      attempt = attempt + '}';
    }
    // último intento de parse
    try {
      return JSON.parse(attempt);
    } catch (e2) {
      // si sigue fallando devolvemos null para indicar que no se pudo parsear
      return null;
    }
  }
}

for (const item of items) {
  try {
    let str = item.json.output;
    let datosParseados = null;

    // Si ya es objeto, usarlo
    if (typeof str !== 'string' && typeof str === 'object' && str !== null) {
      datosParseados = str;
    } else if (typeof str === 'string') {
      // 0) Limpiar delimitadores markdown ```json ... ``` o ``` ... ```
      str = str.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

      // 1) intento de parse robusto usando helper
      // primero normalizamos backslash-u{...} como antes
      let normalized = str.replace(/\\u\{([^}]+)\}/g, (match, inner) => {
        const parts = inner.split(/\\u/);
        let result = '';
        for (let part of parts) {
          if (part === '') continue;
          result += String.fromCodePoint(parseInt(part, 16));
        }
        return result;
      });

      // Intento parse directo y fallback con tryParseJSON
      datosParseados = tryParseJSON(normalized);

      if (!datosParseados) {
        // no se pudo parsear ni en el intento secundario: devolvemos item de error para debugging
        const errorItem = {
          json: {
            error: 'JSON_PARSE_ERROR',
            message: 'No se pudo extraer objeto JSON válido',
            original: item.json.output,
            _raw_extracted: normalized,
            ...item.json
          }
        };
        errorItem.json.flow_name = flowPorDefecto;
        errorItem.json.output = fallbackTexto;
        errorItem.json.text = fallbackTexto;
        errorItem.json.content = fallbackTexto;
        errorItem.json.tipoPregunta = 'FALLBACK';
        nuevosItems.push(errorItem);
        continue; // pasar al siguiente item
      }
    } else {
      // tipo inválido
      const errorItem = {
        json: {
          error: 'INVALID_OUTPUT_TYPE',
          original: item.json.output,
          ...item.json
        }
      };
      errorItem.json.flow_name = flowPorDefecto;
      errorItem.json.output = fallbackTexto;
      errorItem.json.text = fallbackTexto;
      errorItem.json.content = fallbackTexto;
      errorItem.json.tipoPregunta = 'FALLBACK';
      nuevosItems.push(errorItem);
      continue;
    }

    // Des-nidificación defensiva: si 'output' es un string JSON con clave
    // 'output', extraer el objeto interno y hacer merge de sus campos.
    // Cubre desobediencia de formato de la IA (JSON anidado dentro de output).
    if (typeof datosParseados.output === 'string' &&
        datosParseados.output.trim().startsWith('{')) {
      const interno = tryParseJSON(datosParseados.output);
      if (interno && typeof interno === 'object' && interno !== null &&
          interno.output !== undefined) {
        datosParseados = Object.assign({}, datosParseados, interno);
      }
    }

    // --- lógica original conservada ---
    if (!datosParseados.tipoPregunta && datosParseados.output && typeof datosParseados.output === 'string') {
      if (datosParseados.output.includes('Vamos a agendar tu cita') || 
          datosParseados.output.includes('Indíqueme si la atención será por medios propios')) {
        datosParseados.tipoPregunta = 'CITA_DIRECTA';
      }
    }

    if (datosParseados.output && typeof datosParseados.output === 'string') {
      if (datosParseados.output.includes('Para enviarte tus resultados') || 
          datosParseados.output.includes('Foto de cédula') ||
          datosParseados.output.includes('El estudio que necesitas')) {

        datosParseados.tipoPregunta = 'RESULTADOS';

        datosParseados.output = "Hola 👋 Para ayudarte con los resultados, por favor indica el tipo de estudio:\n\n🔬 Si es un examen de LABORATORIO (sangre, orina, heces, etc.) responde 'Laboratorio'.\n📷 Si es un estudio de IMÁGENES (radiografía, ecografía, mamografía, etc.) responde 'Imágenes'.\n\nEn unos segundos te pediré los detalles necesarios.";

        datosParseados.text = datosParseados.output;
        datosParseados.content = datosParseados.output;
      }
    }

    if (datosParseados.output && typeof datosParseados.output === 'string') {
      const match = datosParseados.output.match(/^\s*equipo_asignado:\s*"([^"]*)"\s*$/);
      if (match) {
        datosParseados.equipo_asignado = match[1];
      }
    }

    const resultado = {
      ...item.json,
      ...datosParseados,
      output: datosParseados.output,
      tipoPregunta: datosParseados.tipoPregunta || null
    };

    // Red de seguridad: si el agente devolvió output vacío (intención sin
    // respuesta), reemplazar por el fallback para que los nodos de envío nunca
    // reciban un body vacío que YCloud rechaza.
    if (typeof resultado.output !== 'string' || !resultado.output.trim()) {
      resultado.output = fallbackTexto;
      if (!resultado.tipoPregunta || resultado.tipoPregunta === 'FALLBACK') {
        resultado.tipoPregunta = 'FALLBACK';
      }
      resultado.text = fallbackTexto;
      resultado.content = fallbackTexto;
    }

    // SPEC 18: en modo conversacional (menu_enabled=false) isMenu SIEMPRE
    // false: nunca se envía menú interactivo ni se detecta menú en el output.
    let isMenuValue = false;
    if (menuEnabled) {
      if (datosParseados.isMenu === true) {
        isMenuValue = true;
      } else if (datosParseados.output && typeof datosParseados.output === 'string') {
        const texto = datosParseados.output;
        if (texto.includes('¡Hola! 😊 Bienvenido/a') || 
            texto.includes('Para ayudarte mejor, por favor selecciona') ||
            texto.includes('¿Qué necesitas hoy?')) {
          isMenuValue = true;
        }
      }
    }
    resultado.isMenu = isMenuValue;

    let esPreguntaSiNo = false;
    if (datosParseados.esPreguntaSiNo === true) {
      esPreguntaSiNo = true;
    } else if (datosParseados.output && typeof datosParseados.output === 'string') {
      esPreguntaSiNo = detectarSiNo(datosParseados.output);
    }
    resultado.esPreguntaSiNo = esPreguntaSiNo;

    const equipo = resultado.equipo_asignado;
    let flow_name = '';
    if (typeof datosParseados.flow_name === 'string' && datosParseados.flow_name.trim()) {
      const f = datosParseados.flow_name.trim();
      if (f.startsWith('flujo_')) {
        flow_name = f;
      } else if (mapeoFlow[f]) {
        flow_name = mapeoFlow[f];
      }
    }
    resultado.flow_name = flow_name || mapeoFlow[equipo] || flowPorDefecto;

    // --- Ruteo determinista del menú (SPEC 13, solo menu_enabled=true) ---
    // Si el usuario pide menú o la intención detectada es MENU, se fuerza
    // el texto del menú guardado (con marca) e isMenu=true. La salida de la
    // IA se ignora para este caso. En modo conversacional (SPEC 18) el
    // bloque se omite: la IA responde con la introducción desde el RAG.
    const textoUsuario = (item.json.text || '').toString().toLowerCase();
    let esMenu = datosParseados.tipoPregunta === 'MENU';
    if (!esMenu && textoUsuario) {
      esMenu = keywordsMenu.some(k => k && textoUsuario.includes(k));
    }
    // Texto ultra-corto (≤2 caracteres) → menú determinista (SPEC 14).
    if (!esMenu && textoUsuario && textoUsuario.length <= 2) {
      esMenu = true;
    }
    if (menuEnabled && esMenu && menuTexto) {
      resultado.output = menuTexto;
      resultado.text = menuTexto;
      resultado.content = menuTexto;
      resultado.isMenu = true;
      resultado.tipoPregunta = 'MENU';
      resultado.equipo_asignado = '';
      resultado.flow_name = '';
      resultado.esPreguntaSiNo = false;
    }

    nuevosItems.push({ json: resultado });

  } catch (e) {
    const errorItem = {
      json: {
        error: e.message,
        original: item.json.output,
        ...item.json
      }
    };
    errorItem.json.flow_name = flowPorDefecto;
    nuevosItems.push(errorItem);
  }
}

return nuevosItems;

