const original = $('Cita_con_Equipo_asignado').item.json;
const texto = $json.texto_para_usuario || $json.text || '';
const botones = Array.isArray($json.botones) ? $json.botones.filter(Boolean).slice(0, 3) : [];
const to = original.phone_number_formatted || original.user_number || original.phone_number
  || original.session_id || $('Seteamos_variables').item.json.session_id;
let whatsappPayload = null;
if (botones.length && to) {
  whatsappPayload = {
    from: original.account_id,
    to: to,
    type: "interactive",
    interactive: {
      type: "button",
      body: { text: texto },
      action: { buttons: botones.map(b => ({ type: "reply", reply: { id: b, title: b } })) }
    }
  };
}
return [{ json: {
  ...original,
  output: texto,
  text: texto,
  content: texto,
  modo: $json.modo || original.modo,
  finalizado: $json.finalizado || false,
  imagenes: $json.imagenes || [],
  botones,
  whatsappPayload
} }];
